python -X utf8 -I -c "
import io,re
L=io.open('tools/acts/b758.py',encoding='utf-8').read().replace(chr(13),'').split(chr(10))
print('lines',len(L))
words=['standing_v1354','standing_v1355','_cut','ghcalls','registry_line','doors','sweep','_price','ceiling','mod24','T0','T1','wide','v1.35.4','v1.35.5','(R367)','controls_control','notes_moved','b757_']
cur=None; start=0; hits={}
secs=[]
for i,l in enumerate(L):
    m=re.match(r'^#⟪SECTION (.+?)⟫',l)
    if m:
        cur=(m.group(1),i+1); hits={}
        continue
    if l.startswith('#⟪END⟫') and cur:
        secs.append((cur[0],cur[1],i+1,dict(hits))); cur=None; continue
    if cur:
        for w in words:
            if w in l: hits[w]=hits.get(w,0)+1
print('sections',len(secs))
for n,a,b,h in secs:
    if h: print('%-22s :%d-:%d %d lines  %s'%(n,a,b,b-a,' '.join('%s=%d'%kv for kv in sorted(h.items()))))
print('sections without a hit',sum(1 for s in secs if not s[3]))
"

